run_command:
$ErrorActionPreference='Stop'
$PSNativeCommandUseErrorActionPreference=$false
$registration='732da9ea2355685649e97b74707c2d066aa9dd2f'
if((git rev-parse HEAD).Trim() -ne $registration){throw 'Registered HEAD drifted'}
if(Test-Path -LiteralPath 'outputs/msb_native_supervision_v2'){throw 'Native output already consumed'}
$entry='.superpowers/sdd/2026-10-22-msb-native-supervision-v2-execution'
foreach($name in @('collector_stdout.log','collector_stderr.log')){if(Test-Path -LiteralPath "$entry/$name"){throw 'Single entry log already exists'}}
$p=Get-Content -LiteralPath 'docs/experiment_protocols/msb_native_supervision_v2.json' -Raw | ConvertFrom-Json
if($p.approval_call_id -cne 'call_cdd31dd8986040fb8bd90d6e311f95fc' -or $p.status -cne 'APPROVED_NATIVE_ONLY'){throw 'Exact authorization drifted'}
foreach($s in $p.source_sha256.PSObject.Properties){if((Get-FileHash -LiteralPath $s.Name -Algorithm SHA256).Hash.ToLowerInvariant() -cne $s.Value){throw 'Registered source drifted'}}
$savedBytecode=$env:PYTHONDONTWRITEBYTECODE
$savedUtf8=$env:PYTHONUTF8
$env:PYTHONDONTWRITEBYTECODE='1'
$env:PYTHONUTF8='1'
$code=$null
try{
 & 'D:\成信工科研\人工智能选矿\.venv-training\Scripts\python.exe' '.\scripts\check_msb_native_supervision.py' --root 'D:\成信工科研\人工智能选矿\.worktrees\theory-aware-report' --protocol 'D:\成信工科研\人工智能选矿\.worktrees\theory-aware-report\docs\experiment_protocols\msb_native_supervision_v2.json' --execute-native --approval-call-id 'call_cdd31dd8986040fb8bd90d6e311f95fc' --approval-answer '批准一次固定协议原生验收（推荐）' --registration-commit $registration 1> "$entry/collector_stdout.log" 2> "$entry/collector_stderr.log"
 $code=$LASTEXITCODE
}finally{
 $env:PYTHONDONTWRITEBYTECODE=$savedBytecode
 $env:PYTHONUTF8=$savedUtf8
}
Write-Output ("COLLECTOR_EXIT_CODE="+$code)
if($null -eq $code){throw 'Collector exit code unavailable; stop without retry'}
exit $code
